		[Display(Name = "Daily Profit Goal ($)", Description = "Stop opening trades for the rest of the session once today's closed trades reach this. 0 = off.", Order = 1, GroupName = "9. Daily rules & trading hours")]
		public double DailyProfitGoal { get; set; }

		[NinjaScriptProperty]
		[Range(0.0, double.MaxValue)]
		[Display(Name = "Daily Goal Tolerance ($)", Description = "The goal also counts as reached this much below it (goal 1500, tolerance 100: done from +1400). Covers ticks, slippage and fees.", Order = 2, GroupName = "9. Daily rules & trading hours")]
		public double DailyGoalTolerance { get; set; }

		[NinjaScriptProperty]
		[Range(0.0, double.MaxValue)]
		[Display(Name = "Daily Max Loss ($)", Description = "Stop opening trades for the rest of the session once today's closed trades lose this much. 0 = off.", Order = 3, GroupName = "9. Daily rules & trading hours")]
		public double DailyMaxLoss { get; set; }

		[NinjaScriptProperty]
		[Display(Name = "Block trades that could break max loss", Description = "Don't open a trade if hitting its full stop would take today past the Daily Max Loss.", Order = 4, GroupName = "9. Daily rules & trading hours")]
		public bool BlockTradesOverDailyLoss { get; set; }

		[NinjaScriptProperty]
		[Display(Name = "Use Trading Hours", Description = "Only open trades between Start and End time (the chart's time zone, bar close time). The window may cross midnight, e.g. 18:00 to 16:45.", Order = 5, GroupName = "9. Daily rules & trading hours")]
		public bool UseTradingHours { get; set; }

		[NinjaScriptProperty]
		[PropertyEditor("NinjaTrader.Gui.Tools.TimeEditorKey")]
		[Display(Name = "Start Time", Order = 6, GroupName = "9. Daily rules & trading hours")]
		public DateTime TradeStartTime { get; set; }

		[NinjaScriptProperty]
		[PropertyEditor("NinjaTrader.Gui.Tools.TimeEditorKey")]
		[Display(Name = "End Time", Order = 7, GroupName = "9. Daily rules & trading hours")]
		public DateTime TradeEndTime { get; set; }

		[NinjaScriptProperty]
		[Display(Name = "Flatten at End Time", Description = "Close any open trade on the first bar at or after the End Time.", Order = 8, GroupName = "9. Daily rules & trading hours")]
		public bool FlattenAtEndTime { get; set; }

		[NinjaScriptProperty]
		[Display(Name = "Use Account Rotation", Description = "Simulate prop accounts: each trade goes to one account by the rotation mode, with each firm's rules. Daily goal / loss (group 9) then apply per account. Off = unchanged logic.", Order = 1, GroupName = "10. Prop accounts (simulated rotation)")]
		public bool UseAccountRotation { get; set; }

		[Display(Name = "Accounts", Description = "name=plan, separated by commas. Plans: Topstep50K, Topstep50K-DLL, Topstep100K, Topstep150K, LucidFlex50K, LucidPro50K, Custom.", Order = 2, GroupName = "10. Prop accounts (simulated rotation)")]
		public string PropAccountList { get; set; }

		[NinjaScriptProperty]
		[Display(Name = "Rotation Mode", Description = "EveryTrade: each new trade goes to the next account. UntilDayDone: stay on an account until its daily goal or a loss limit ends its day, then move on.", Order = 3, GroupName = "10. Prop accounts (simulated rotation)")]
		public RutaMirrorV6RotationMode RotationMode { get; set; }

		[NinjaScriptProperty]
		[Display(Name = "Block trades that could fail the account", Description = "Skip an account for a trade whose full stop would cross that account's max loss line.", Order = 4, GroupName = "10. Prop accounts (simulated rotation)")]
		public bool BlockTradesOverAccountMaxLoss { get; set; }

		[Display(Name = "Restart Finished Accounts", Description = "When an evaluation passes or fails, start a new one in that slot at the next session (to measure passes per month).", Order = 5, GroupName = "10. Prop accounts (simulated rotation)")]
		public bool RestartFinishedAccounts { get; set; }

		[Range(0.0, double.MaxValue)]
		[Display(Name = "Evaluation Fee ($)", Description = "Cost of one evaluation, for the totals line.", Order = 6, GroupName = "10. Prop accounts (simulated rotation)")]
		public double EvaluationFee { get; set; }

		[Range(1.0, double.MaxValue)]
		[Display(Name = "Custom: Profit Target ($)", Order = 7, GroupName = "10. Prop accounts (simulated rotation)")]
		public double CustomProfitTarget { get; set; }

		[Range(1.0, double.MaxValue)]
		[Display(Name = "Custom: Max Loss ($)", Order = 8, GroupName = "10. Prop accounts (simulated rotation)")]
		public double CustomMaxLoss { get; set; }

		[Display(Name = "Custom: Drawdown Type", Description = "EodTrailing: trails the highest end-of-day balance. IntradayTrailing: trails the highest balance incl. open profit. Static: fixed. Trailing lines stop at the starting balance.", Order = 9, GroupName = "10. Prop accounts (simulated rotation)")]
		public RutaMirrorV6DrawdownType CustomDrawdownType { get; set; }

		[Range(0.0, double.MaxValue)]
		[Display(Name = "Custom: Daily Loss Limit ($)", Description = "0 = none. Hitting it ends the account's day (not the evaluation).", Order = 10, GroupName = "10. Prop accounts (simulated rotation)")]
		public double CustomDailyLossLimit { get; set; }

		[Range(0.0, 100.0)]
		[Display(Name = "Custom: Consistency (%)", Description = "Best day must be at most this % of the total profit. 0 = no rule.", Order = 11, GroupName = "10. Prop accounts (simulated rotation)")]
		public double CustomConsistencyPct { get; set; }

		[Display(Name = "Show Accounts Dashboard", Order = 12, GroupName = "10. Prop accounts (simulated rotation)")]
		public bool ShowAccountsDashboard { get; set; }

		[NinjaScriptProperty]
		[Display(Name = "Sizing Mode", Description = "FixedContracts, or RiskPerTrade (= the Pine 'USD' sizing without martingale). Ignored in Dollars / DollarsSizedByAtr.", Order = 1, GroupName = "5. Position Size")]
		public RutaMirrorV6Sizing SizingMode { get; set; }

		[NinjaScriptProperty]
		[Range(1, int.MaxValue)]
		[Display(Name = "Fixed Contracts", Description = "Used by FixedContracts sizing and by Dollars mode. Ignored in DollarsSizedByAtr.", Order = 2, GroupName = "5. Position Size")]
		public int FixedContracts { get; set; }

		[NinjaScriptProperty]
		[Range(1.0, double.MaxValue)]
		[Display(Name = "Risk Per Trade ($)", Description = "RiskPerTrade sizing with AtrMultiple units only: contracts = floor(risk / (SL ATR mult x ATR x point value)). Ignored in Dollars modes (there Stop Loss $ is the risk).", Order = 3, GroupName = "5. Position Size")]
		public double RiskPerTrade { get; set; }

		[NinjaScriptProperty]
		[Range(1, int.MaxValue)]
		[Display(Name = "Max Contracts", Description = "Safety cap for ATR sizing. In DollarsSizedByAtr a capped (or 1-contract) entry keeps the $ amounts, so its stop is wider (or tighter) than the ATR target.", Order = 4, GroupName = "5. Position Size")]
		public int MaxContracts { get; set; }

		[NinjaScriptProperty]
		[Display(Name = "Enable Orders", Description = "Off = only draw the TradingView trades (indicator mode)", Order = 1, GroupName = "6. Execution")]
		public bool EnableOrders { get; set; }

		[Display(Name = "Show Buy/Sell Signals", Order = 1, GroupName = "7. Chart / Compare")]
		public bool ShowSignals { get; set; }

		[Display(Name = "Show TradingView Fills", Description = "Order labels + diamond at the TradingView fill price (bar close)", Order = 2, GroupName = "7. Chart / Compare")]
		public bool ShowTvFills { get; set; }

		[Display(Name = "Show Trade Lines", Order = 3, GroupName = "7. Chart / Compare")]
		public bool ShowTradeLines { get; set; }

		[Display(Name = "Show Skipped Setups", Description = "RSI trigger fired but no trade: shows the blocking filter, turns green/red with the hindsight result", Order = 4, GroupName = "7. Chart / Compare")]
		public bool ShowSkippedSetups { get; set; }

		[Display(Name = "Show Stats Box", Order = 5, GroupName = "7. Chart / Compare")]
		public bool ShowStats { get; set; }

		[Display(Name = "Print Trades To Output", Order = 6, GroupName = "7. Chart / Compare")]
		public bool PrintTradeList { get; set; }

		[Display(Name = "Export Trades CSV", Description = "Documents\\NinjaTrader 8\\RutaCryptoMirrorV6\\<instrument>_trades.csv (+ _setups.csv)", Order = 7, GroupName = "7. Chart / Compare")]
		public bool ExportTradesCsv { get; set; }

		[Display(Name = "Export Bar Values CSV", Description = "Per-bar HA / RSI / osc / ATR values to compare with the debug Pine script", Order = 8, GroupName = "7. Chart / Compare")]
		public bool ExportBarsCsv { get; set; }
